## Multiple values

When `multiple={true}`, the user can select multiple values. These selected values, referred to as "items" can be customized using the `renderValue` prop.

- The `getItemProps` getter supplies essential props like `data-item-index`, `disabled`, `tabIndex` and others. Make sure to spread them on each rendered item.
- If using a custom component other than a Material UI Chip, destructure the `onDelete` prop as it's specific to the Material UI Chip.

```tsx
import * as React from 'react';
import Chip from '@mui/material/Chip';
import Autocomplete from '@mui/material/Autocomplete';
import TextField from '@mui/material/TextField';
import Stack from '@mui/material/Stack';

const removeDescription = 'Press Backspace or Delete to remove';

function getInputDescription(valueLength: number) {
  return valueLength > 0
    ? `${valueLength} selected. From the start of the input, press Left Arrow to focus the selected items`
    : undefined;
}

export default function Tags() {
  const [standardValue, setStandardValue] = React.useState([top100Films[13]]);
  const [outlinedValue, setOutlinedValue] = React.useState([top100Films[13]]);
  const [filledValue, setFilledValue] = React.useState<string[]>([
    top100Films[13].title,
  ]);
  const [readOnlyValue] = React.useState([
    top100Films[12].title,
    top100Films[13].title,
  ]);

  return (
    <Stack spacing={3} sx={{ width: 500 }}>
      <Autocomplete
        multiple
        id="tags-standard"
        options={top100Films}
        getOptionLabel={(option) => option.title}
        value={standardValue}
        onChange={(event, newValue) => {
          setStandardValue(newValue);
        }}
        slotProps={{
          chip: {
            'aria-description': removeDescription,
          },
        }}
        renderInput={(params) => (
          <TextField
            {...params}
            variant="standard"
            label="Multiple values"
            placeholder="Favorites"
            slotProps={{
              ...params.slotProps,
              htmlInput: {
                ...params.slotProps.htmlInput,
                'aria-description': getInputDescription(standardValue.length),
              },
            }}
          />
        )}
      />
      <Autocomplete
        multiple
        id="tags-outlined"
        options={top100Films}
        getOptionLabel={(option) => option.title}
        value={outlinedValue}
        onChange={(event, newValue) => {
          setOutlinedValue(newValue);
        }}
        filterSelectedOptions
        slotProps={{
          chip: {
            'aria-description': removeDescription,
          },
        }}
        renderInput={(params) => (
          <TextField
            {...params}
            label="filterSelectedOptions"
            placeholder="Favorites"
            slotProps={{
              ...params.slotProps,
              htmlInput: {
                ...params.slotProps.htmlInput,
                'aria-description': getInputDescription(outlinedValue.length),
              },
            }}
          />
        )}
      />
      <Autocomplete
        multiple
        id="tags-filled"
        options={top100Films.map((option) => option.title)}
        value={filledValue}
        onChange={(event, newValue) => {
          setFilledValue(newValue);
        }}
        freeSolo
        renderValue={(value: readonly string[], getItemProps) =>
          value.map((option: string, index: number) => {
            const { key, ...itemProps } = getItemProps({ index });
            return (
              <Chip
                variant="outlined"
                label={option}
                key={key}
                aria-description={removeDescription}
                {...itemProps}
              />
            );
          })
        }
        renderInput={(params) => (
          <TextField
            {...params}
            variant="filled"
            label="freeSolo"
            placeholder="Favorites"
            slotProps={{
              ...params.slotProps,
              htmlInput: {
                ...params.slotProps.htmlInput,
                'aria-description': getInputDescription(filledValue.length),
              },
            }}
          />
        )}
      />
      <Autocomplete
        multiple
        id="tags-readOnly"
        options={top100Films.map((option) => option.title)}
        defaultValue={readOnlyValue}
        readOnly
        renderInput={(params) => (
          <TextField
            {...params}
            label="readOnly"
            placeholder="Favorites"
            slotProps={{
              ...params.slotProps,
              htmlInput: {
                ...params.slotProps.htmlInput,
                'aria-description': getInputDescription(readOnlyValue.length),
              },
            }}
          />
        )}
      />
    </Stack>
  );
}

